import { test, expect } from '@playwright/test';

test.describe('Login to Secure Area', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/login');
  });

  test('should display login form with username and password fields', async ({ page }) => {
    const usernameField = page.locator('#username');
    const passwordField = page.locator('#password');
    const submitButton = page.locator('button[type="submit"]');

    await expect(usernameField).toBeVisible();
    await expect(passwordField).toBeVisible();
    await expect(submitButton).toBeVisible();
  });

  test('should successfully log in with valid credentials and display success message', async ({ page }) => {
    const usernameField = page.locator('#username');
    const passwordField = page.locator('#password');
    const submitButton = page.locator('button[type="submit"]');

    await usernameField.fill('tomsmith');
    await passwordField.fill('SuperSecretPassword!');
    await submitButton.click();

    await expect(page).toHaveURL(/\/secure/);

    const flashBanner = page.locator('.flash.success');
    await expect(flashBanner).toBeVisible();
    await expect(flashBanner).toContainText('You logged into a secure area!');
  });

  test('should display error message with invalid credentials', async ({ page }) => {
    const usernameField = page.locator('#username');
    const passwordField = page.locator('#password');
    const submitButton = page.locator('button[type="submit"]');

    await usernameField.fill('invaliduser');
    await passwordField.fill('wrongpassword');
    await submitButton.click();

    const errorBanner = page.locator('.flash.error');
    await expect(errorBanner).toBeVisible();
    await expect(errorBanner).toContainText('Your username is invalid!');
  });
});
